import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"缺页路径","description":"","frontmatter":{"title":"缺页路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-fault-path.md","filePath":"cs/page-fault-path.md","lastUpdated":1789023840000}'),h={name:"cs/page-fault-path.md"};function A(m,a,E,_,u,B){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="缺页路径" tabindex="-1">缺页路径 <a class="header-anchor" href="#缺页路径" aria-label="Permalink to &quot;缺页路径&quot;">​</a></h1><div class="epigraph"><p>缺页陷入之后，内核要判断：非法、补页、写时复制，还是发给进程一个信号。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/demand-paging">上一课</a>给出策略：合法访问可以在触及才占帧。<a href="/cs/paging-vm">分页</a>的缺页异常已经能进内核，本课不重导页表。<a href="/cs/brk-heap">brk 与堆</a>只保证区间合法。缺口是<strong>路径</strong>：硬件向量之后，内核如何找到那一段 VMA，并决定 minor/major、杀进程或重试指令。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一类「页表项无效」至少有三种前途：地址不在任何 VMA（野指针）；在 VMA 里但还没有帧（按需）；在 VMA 里且有帧但不能写（保护或后课 COW）。若缺页处理把三者混成一种「再配一页」，只读文本会被写成可写。缺口不是 TLB 怎么查，而是：取故障地址 → 查进程的虚区间树 → 对照错误码里的写/用户/指令位 → 分配或拒绝。</p><p>本课不把每种架构的 error code 位图背完。</p><p><span class="marginnote">minor 缺页：页已在内存（如页 Cache），只需填表。major：要读磁盘或 swap。会计进进程的缺页计数，调度与后课抖动会用到。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入口沿用组成课的精确异常：保存 trapframe，内核用故障 VA 查 VMA。无 VMA 或权限不够：投递 <code>SIGSEGV</code>（后课信号），不配帧。有 VMA：按需分配帧、必要时从文件读入、置权限、冲本 CPU 的 <a href="/cs/tlb-translate">TLB</a>，返回用户重试。栈守卫页可触发一次扩展，仍须受上限约束。</p>',9)),(e(),n(c,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%E9%99%B7%E5%85%A5%22%5D%20--%3E%20VMA%5B%22%E6%9F%A5%20VMA%22%5D%0A%20%20VMA%20--%3E%20BAD%5B%22%E6%97%A0%E5%8C%BA%E9%97%B4%E6%88%96%E8%B6%8A%E6%9D%83%3A%20%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20VMA%20--%3E%20FILL%5B%22%E5%90%88%E6%B3%95%3A%20%E9%85%8D%E5%B8%A7%E6%88%96%E5%A1%AB%20Cache%22%5D%0A%20%20FILL%20--%3E%20RETRY%5B%22%E8%BF%94%E5%9B%9E%E9%87%8D%E8%AF%95%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>路径把「按需」从口号收成可审计的分支：文件页走 inode 与后课页 Cache；匿名页填零。内核自己的缺页（例如拷贝用户缓冲时）不能杀内核，只能把错误返回给系统调用。这与用户指令缺页同走 MMU，处理函数不同。</p><p>不要在这里重写多级页表 walker：那是分页课与 TLB 课的对象。本课只使用「硬件已经指出 VA 与错误类型」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>userfaultfd</code> 把缺页交给用户态处理的全部协议。不把 NUMA 的远程帧分配写成默认。指令与数据缺页在统计上可分开，教学上同一条路径。多核上改页表之后其他 CPU 的 TLB 仍可能是旧的，那是后课 shootdown。</p><p>后课默认：缺页已能对 4K 页正确补表。TLB 压力与页表层数，下一课用大页来减。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缺页先对 VMA 与权限分类，再配帧或发信号。</li><li>minor/major 区分「是否访盘」，不改页表格式。</li><li>大页如何减少翻译项，是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const V=l(h,[["render",A]]);export{T as __pageData,V as default};
